import api.Response;
import app.MenuApp;
import db.InMemoryDatabase;

import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class MenuBoardTest {
    static String drinks;
    static String americano;
    static String latte;
    static String icedTea;

    static void seed(MenuApp app) {
        drinks = TestSupport.id(app.handle("POST", "/admin/categories", "mia", Map.of("title", "Drinks")));
        americano = TestSupport.id(app.handle("POST", "/admin/categories/" + drinks + "/items", "mia", Map.of("name", "Americano", "price", "3.00")));
        latte = TestSupport.id(app.handle("POST", "/admin/categories/" + drinks + "/items", "mia", Map.of("name", "Latte", "price", "4.20")));
        icedTea = TestSupport.id(app.handle("POST", "/admin/categories/" + drinks + "/items", "mia", Map.of("name", "Iced Tea", "price", "3.50")));
    }

    public static void main(String[] args) throws Exception {
        // 1) one request after another
        {
            MenuApp app = MenuApp.create(new InMemoryDatabase());
            seed(app);
            TestSupport.check(TestSupport.names(app, drinks).equals(List.of("Americano", "Latte", "Iced Tea")), "new items go to the bottom");
            Response moved = app.handle("POST", "/admin/items/" + icedTea + "/move", "mia", Map.of("index", "0"));
            TestSupport.check(moved.status() == 204, "move accepted");
            app.handle("PATCH", "/admin/items/" + latte, "noah", Map.of("price", "4.40"));
            app.handle("PATCH", "/admin/items/" + icedTea, "noah", Map.of("name", "Peach Iced Tea"));
            TestSupport.check(TestSupport.names(app, drinks).equals(List.of("Peach Iced Tea", "Americano", "Latte")),
                    "sequential edits: " + TestSupport.names(app, drinks));
            TestSupport.check("$4.40".equals(TestSupport.price(app, drinks, "Latte")), "price change shows on the board");
            app.handle("PATCH", "/admin/items/" + americano, "noah", Map.of("visible", "false"));
            TestSupport.check(TestSupport.names(app, drinks).equals(List.of("Peach Iced Tea", "Latte")), "hidden items are not on the board");
            TestSupport.check(app.handle("POST", "/admin/items/nope/move", "mia", Map.of("index", "1")).status() == 404, "unknown item → 404");
            TestSupport.check(app.handle("PATCH", "/admin/items/" + latte, "mia", Map.of("name", "  ")).status() == 400, "blank name → 400");
        }

        // 2) two staff tablets at the same time: one renames a drink while the other drags it to the top
        {
            PausingDatabase db = new PausingDatabase(new InMemoryDatabase());
            MenuApp app = MenuApp.create(db);
            seed(app);

            Thread renamer = new Thread(() -> app.handle("PATCH", "/admin/items/" + icedTea, "noah", Map.of("name", "Cold Brew")), "tablet-1");
            db.pauseAfterRead(renamer, "menu_item", icedTea);
            renamer.start();
            db.reached.await(2, TimeUnit.SECONDS);

            Thread mover = new Thread(() -> app.handle("POST", "/admin/items/" + icedTea + "/move", "mia", Map.of("index", "0")), "tablet-2");
            mover.start();
            mover.join(500);
            db.release.countDown();
            renamer.join(5000);
            mover.join(5000);

            List<String> board = TestSupport.names(app, drinks);
            TestSupport.check(board.contains("Cold Brew"), "renamed drink shows its new name (board " + board + ")");
            TestSupport.check(board.equals(List.of("Cold Brew", "Americano", "Latte")),
                    "drink moved to the top stays on top after the rename (board " + board + ")");
        }

        TestSupport.finish("menu board");
    }
}
import db.Database;

import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/** Test double: holds one chosen thread right after it first reads a given row, so request timing is reproducible. */
public class PausingDatabase implements Database {
    private final Database delegate;
    private final AtomicBoolean fired = new AtomicBoolean();
    private volatile Thread target;
    private volatile String table;
    private volatile String id;
    final CountDownLatch reached = new CountDownLatch(1);
    final CountDownLatch release = new CountDownLatch(1);

    public PausingDatabase(Database delegate) {
        this.delegate = delegate;
    }

    void pauseAfterRead(Thread thread, String table, String id) {
        this.table = table;
        this.id = id;
        this.target = thread;
    }

    @Override
    public Map<String, Object> select(String t, String i) {
        Map<String, Object> row = delegate.select(t, i);
        if (Thread.currentThread() == target && t.equals(table) && i.equals(id) && fired.compareAndSet(false, true)) {
            reached.countDown();
            try {
                release.await(3, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return row;
    }

    @Override
    public List<Map<String, Object>> selectAll(String t) {
        return delegate.selectAll(t);
    }

    @Override
    public void insert(String t, String i, Map<String, Object> row) {
        delegate.insert(t, i, row);
    }

    @Override
    public void update(String t, String i, Map<String, Object> columns) {
        delegate.update(t, i, columns);
    }

    @Override
    public long version() {
        return delegate.version();
    }
}
import api.Response;
import app.MenuApp;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class TestSupport {
    static int failed = 0;

    private TestSupport() {
    }

    static void check(boolean cond, String msg) {
        System.out.println((cond ? "ok   - " : "FAIL - ") + msg);
        if (!cond) {
            failed++;
        }
    }

    static void finish(String suite) {
        if (failed > 0) {
            System.out.println(suite + ": " + failed + " check(s) failed");
            System.exit(1);
        }
        System.out.println(suite + ": all checks passed");
    }

    static String id(Response r) {
        Matcher m = Pattern.compile("\"id\":\"([^\"]*)\"").matcher(r.body());
        if (!m.find()) {
            throw new IllegalStateException("no id in " + r);
        }
        return m.group(1);
    }

    /** Item names on the public board, top to bottom. */
    static List<String> names(MenuApp app, String category) {
        Response r = app.handle("GET", "/menus/" + category, null, Map.of());
        List<String> names = new ArrayList<>();
        Matcher m = Pattern.compile("\"name\":\"([^\"]*)\"").matcher(r.body());
        while (m.find()) {
            names.add(m.group(1));
        }
        return names;
    }

    static String price(MenuApp app, String category, String name) {
        Response r = app.handle("GET", "/menus/" + category, null, Map.of());
        Matcher m = Pattern.compile("\"name\":\"" + Pattern.quote(name) + "\",\"price\":\"([^\"]*)\"").matcher(r.body());
        return m.find() ? m.group(1) : null;
    }
}
import db.InMemoryDatabase;
import domain.MenuItem;
import orm.Transactions;
import repo.MenuRepository;
import util.Money;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class MenuUnitChecks {
    public static void main(String[] args) {
        TestSupport.check(Money.format(450).equals("$4.50"), "money: format");
        TestSupport.check(Money.format(-5).equals("-$0.05"), "money: negative");
        TestSupport.check(Money.parse("$4.5") == 450 && Money.parse("12") == 1200 && Money.parse("0.07") == 7, "money: parse");

        InMemoryDatabase db = new InMemoryDatabase();
        db.insert("t", "a", Map.of("x", 1, "y", "one"));
        db.update("t", "a", Map.of("y", "two"));
        TestSupport.check(db.select("t", "a").equals(Map.of("id", "a", "x", 1, "y", "two")), "db: update");
        db.select("t", "a").put("x", 99);
        TestSupport.check(Integer.valueOf(1).equals(db.select("t", "a").get("x")), "db: returned rows are copies");
        long v = db.version();
        TestSupport.check(v == 2, "db: version counts writes");

        List<MenuItem> items = new ArrayList<>(List.of(
                new MenuItem("1", "c", "banana", 100, 20, true),
                new MenuItem("2", "c", "Apple", 100, 20, true),
                new MenuItem("3", "c", "cherry", 100, 10, true)));
        items.sort(MenuRepository.BOARD_ORDER);
        TestSupport.check(items.get(0).id().equals("3") && items.get(1).id().equals("2") && items.get(2).id().equals("1"),
                "board order: position then name, case-insensitive");

        InMemoryDatabase db2 = new InMemoryDatabase();
        Transactions tx = new Transactions(db2);
        MenuRepository repo = new MenuRepository();
        tx.run(s -> repo.add(s, new MenuItem("i1", "c", "Soup", 500, 10, true)));
        long before = db2.version();
        String name = tx.read(s -> {
            MenuItem it = repo.item(s, "i1");
            it.rename("changed only in memory");
            return repo.item(s, "i1").name();
        });
        TestSupport.check(name.equals("changed only in memory"), "session: identity map returns the same object");
        TestSupport.check(db2.version() == before && db2.select("menu_item", "i1").get("name").equals("Soup"), "read-only session writes nothing");

        TestSupport.finish("unit");
    }
}

