package orm;

import java.util.Map;

/** Converts between an entity object and its table row. */
public interface EntityMapper<T> {
    String table();

    String idOf(T entity);

    Map<String, Object> toRow(T entity);

    T fromRow(Map<String, Object> row);
}
package orm;

import db.Database;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Unit of work. Entities loaded through a session are tracked; {@link #flush()} writes them back,
 * so services only change objects and never call update themselves.
 */
public class Session {
    private record Managed(EntityMapper<Object> mapper, Object entity) {}

    private final Database db;
    private final Map<String, Managed> identityMap = new LinkedHashMap<>();
    private final List<Runnable> afterCommit = new ArrayList<>();

    Session(Database db) {
        this.db = db;
    }

    public <T> T find(EntityMapper<T> mapper, String id) {
        String key = mapper.table() + "/" + id;
        Managed managed = identityMap.get(key);
        if (managed != null) {
            return cast(managed.entity());
        }
        Map<String, Object> row = db.select(mapper.table(), id);
        if (row == null) {
            return null;
        }
        return track(mapper, mapper.fromRow(row));
    }

    public <T> List<T> findWhere(EntityMapper<T> mapper, Predicate<Map<String, Object>> filter) {
        List<T> result = new ArrayList<>();
        for (Map<String, Object> row : db.selectAll(mapper.table())) {
            if (!filter.test(row)) {
                continue;
            }
            String key = mapper.table() + "/" + row.get("id");
            Managed managed = identityMap.get(key);
            result.add(managed != null ? cast(managed.entity()) : track(mapper, mapper.fromRow(row)));
        }
        return result;
    }

    public <T> void add(EntityMapper<T> mapper, T entity) {
        db.insert(mapper.table(), mapper.idOf(entity), mapper.toRow(entity));
        track(mapper, entity);
    }

    public void afterCommit(Runnable action) {
        afterCommit.add(action);
    }

    void flush() {
        for (Managed m : identityMap.values()) {
            db.update(m.mapper().table(), m.mapper().idOf(m.entity()), m.mapper().toRow(m.entity()));
        }
    }

    void runAfterCommit() {
        for (Runnable r : afterCommit) {
            r.run();
        }
    }

    @SuppressWarnings("unchecked")
    private <T> T track(EntityMapper<T> mapper, T entity) {
        identityMap.put(mapper.table() + "/" + mapper.idOf(entity), new Managed((EntityMapper<Object>) mapper, entity));
        return entity;
    }

    @SuppressWarnings("unchecked")
    private static <T> T cast(Object o) {
        return (T) o;
    }
}
package orm;

import db.Database;

import java.util.function.Consumer;
import java.util.function.Function;

/** Runs work in a fresh session and flushes it when the work returns normally. */
public class Transactions {
    private final Database db;

    public Transactions(Database db) {
        this.db = db;
    }

    public <R> R call(Function<Session, R> work) {
        Session session = new Session(db);
        R result = work.apply(session);
        session.flush();
        session.runAfterCommit();
        return result;
    }

    /** For queries: entities are loaded the same way but nothing is written back. */
    public <R> R read(Function<Session, R> work) {
        return work.apply(new Session(db));
    }

    public void run(Consumer<Session> work) {
        call(s -> {
            work.accept(s);
            return null;
        });
    }
}
package repo;

import domain.Category;
import orm.EntityMapper;

import java.util.LinkedHashMap;
import java.util.Map;

public class CategoryMapper implements EntityMapper<Category> {
    public static final CategoryMapper INSTANCE = new CategoryMapper();

    @Override
    public String table() {
        return "category";
    }

    @Override
    public String idOf(Category entity) {
        return entity.id();
    }

    @Override
    public Map<String, Object> toRow(Category e) {
        Map<String, Object> row = new LinkedHashMap<>();
        row.put("title", e.title());
        return row;
    }

    @Override
    public Category fromRow(Map<String, Object> row) {
        return new Category((String) row.get("id"), (String) row.get("title"));
    }
}
package repo;

import domain.MenuItem;
import orm.EntityMapper;

import java.util.LinkedHashMap;
import java.util.Map;

public class MenuItemMapper implements EntityMapper<MenuItem> {
    public static final MenuItemMapper INSTANCE = new MenuItemMapper();

    @Override
    public String table() {
        return "menu_item";
    }

    @Override
    public String idOf(MenuItem entity) {
        return entity.id();
    }

    @Override
    public Map<String, Object> toRow(MenuItem e) {
        Map<String, Object> row = new LinkedHashMap<>();
        row.put("category_id", e.categoryId());
        row.put("name", e.name());
        row.put("price_cents", e.priceCents());
        row.put("position", e.position());
        row.put("visible", e.visible());
        return row;
    }

    @Override
    public MenuItem fromRow(Map<String, Object> row) {
        return new MenuItem(
                (String) row.get("id"),
                (String) row.get("category_id"),
                (String) row.get("name"),
                ((Number) row.get("price_cents")).longValue(),
                ((Number) row.get("position")).intValue(),
                Boolean.TRUE.equals(row.get("visible")));
    }
}
package repo;

import domain.Category;
import domain.MenuItem;
import orm.Session;

import java.util.Comparator;
import java.util.List;

public class MenuRepository {
    /** Board order: position, then name so equal positions still list deterministically. */
    public static final Comparator<MenuItem> BOARD_ORDER =
            Comparator.comparingInt(MenuItem::position).thenComparing(MenuItem::name, String.CASE_INSENSITIVE_ORDER);

    public MenuItem item(Session session, String id) {
        return session.find(MenuItemMapper.INSTANCE, id);
